import importlib.util,json,numpy as np,pymc as pm,pytensor
def load(p,n):
  spec=importlib.util.spec_from_file_location(n,p);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);return m
pool=json.load(open('../../../novelty_pool.json'))
for r in pool: r['rating']=0
params={'kind_weights':[0.461,0.535,0.004],'mean_width':49.0,'shape':4.45}
out={}
for name,p,fam in [('chain','chain_gamma.py',[0.059,0.03,0.049,0.246,0.294,0.308,0.004,0.005,0.004]),('base','base.py',[0.059,0.031,0.05,0.252,0.286,0.313,0.004,0.005])]:
  m=load(p,name); d=m.prepare_observed(pool)
  with m.model:
    pm.set_data(d)
    fam=np.array(fam);fam/=fam.sum()
    pt_={'kind_weights':np.array(params['kind_weights']),'mean_width':params['mean_width'],'shape':params['shape'],'family_weights':fam}
    vals=[]
    for v in m.model.value_vars:
      rv=m.model.values_to_rvs[v]; tr=m.model.rvs_to_transforms[rv]
      x=pt_[rv.name]; vals.append(tr.forward(pytensor.tensor.as_tensor(np.asarray(x,dtype='float64'))).eval() if tr else x)
    fn=pytensor.function(m.model.value_vars, m.model.replace_rvs_by_values([m.model['p_yes']])[0], on_unused_input='ignore')
    out[name]=fn(*vals)
dd=out['chain']-out['base']; print('rmse',np.sqrt((dd**2).mean()))
for j in np.argsort(-np.abs(dd))[:10]: print(pool[j]['number_set'],pool[j]['target'],round(out['chain'][j],2),round(out['base'][j],2))
EOF
